TEST(EquivalenceProbe, SingleItemsAcrossDomain) {
    int mismatches = 0;
    for (const Case& c : kCases) {
        std::vector<Item> items(1, Item(kNames[c.name], c.sellIn, c.quality));
        GildedRose app(items);
        app.updateQuality();
        if (items.size() != 1u || items[0].name != kNames[c.name] || items[0].sellIn != c.expectedSellIn ||
            items[0].quality != c.expectedQuality) {
            if (++mismatches <= 5) {
                ADD_FAILURE() << kNames[c.name] << " sellIn=" << c.sellIn << " quality=" << c.quality;
            }
        }
    }
    EXPECT_EQ(0, mismatches) << "of 14678 cases";
}

TEST(EquivalenceProbe, MixedInventories) {
    int mismatches = 0;
    for (const Inventory& inv : kInventories) {
        std::vector<Item> items;
        for (int n = 0; n < 8; ++n) items.push_back(Item(kNames[n], inv.sellIn, n == 3 ? 80 : inv.quality));
        GildedRose app(items);
        app.updateQuality();
        if (items.size() != 8u) {
            ++mismatches;
            continue;
        }
        for (int n = 0; n < 8; ++n) {
            if (items[n].name != kNames[n] || items[n].sellIn != inv.expected[n][0] ||
                items[n].quality != inv.expected[n][1]) {
                if (++mismatches <= 5) ADD_FAILURE() << kNames[n] << " in inventory sellIn=" << inv.sellIn;
            }
        }
    }
    EXPECT_EQ(0, mismatches);
}

TEST(EquivalenceProbe, EmptyInventory) {
    std::vector<Item> items;
    GildedRose app(items);
    app.updateQuality();
    EXPECT_TRUE(items.empty());
}
